typedef struct {
    int *keys, *counts;
    bool *used;
    size_t mask;
} CountMap;

CountMap cm_new(size_t n) {
    size_t cap = 16;
    while (cap < 2 * n) cap <<= 1;
    CountMap m;
    m.keys = malloc(cap * sizeof(int));
    m.counts = calloc(cap, sizeof(int));
    m.used = calloc(cap, sizeof(bool));
    m.mask = cap - 1;
    return m;
}

static size_t cm_slot(const CountMap* m, int key) {
    size_t i = ((uint32_t)key * 2654435761u) & m->mask;
    while (m->used[i] && m->keys[i] != key) i = (i + 1) & m->mask;
    return i;
}

void cm_add(CountMap* m, int key) {
    size_t i = cm_slot(m, key);
    m->used[i] = true;
    m->keys[i] = key;
    m->counts[i]++;
}

int cm_get(const CountMap* m, int key) {
    size_t i = cm_slot(m, key);
    return m->used[i] ? m->counts[i] : 0;
}

int firstUnique(const int* nums, int n) {
    CountMap count = cm_new(n);
    for (int i = 0; i < n; i++) cm_add(&count, nums[i]);
    int answer = -1;
    for (int i = 0; i < n; i++) {
        if (cm_get(&count, nums[i]) == 1) {
            answer = nums[i];
            break;
        }
    }
    free(count.keys); free(count.counts); free(count.used);
    return answer;
}

