def same_letters(a, b):
    if len(a) != len(b):
        return False
    diff = [0] * 26
    for ch in a:
        diff[ord(ch) - ord('a')] += 1
    for ch in b:
        k = ord(ch) - ord('a')
        diff[k] -= 1
        if diff[k] < 0:
            return False
    return True

code.java:
static boolean sameLetters(String a, String b) {
    if (a.length() != b.length()) return false;
    int[] diff = new int[26];
    for (char ch : a.toCharArray()) diff[ch - 'a']++;
    for (char ch : b.toCharArray()) {
        if (--diff[ch - 'a'] < 0) return false;
    }
    return true;
}

