bool sameLetters(const char* a, const char* b) {
    if (strlen(a) != strlen(b)) return false;
    int diff[26] = {0};
    for (const char* p = a; *p; p++) diff[*p - 'a']++;
    for (const char* p = b; *p; p++) {
        if (--diff[*p - 'a'] < 0) return false;
    }
    return true;
}

